/bin/zsh -lc "node --disable-warning=ExperimentalWarning --input-type=module <<'JS'
import assert from 'node:assert/strict';
import { NotesStore, NotesError } from './src/store.js';
import { SEED_NOTES } from './src/seed.js';
import { handleMessage } from './src/server.js';
const store = new NotesStore();
try {
  const ids = store.importNotes(SEED_NOTES);
  for (const tag of ['travel', 'Travel', 'TRAVEL']) {
    assert.deepEqual(store.search('ferry', { tag }).map(n => n.id), [ids[3], ids[1], ids[0]]);
  }
  assert.deepEqual(store.recall(ids[0]).tags, ['Boats', 'Travel']);
  store.update(ids[0], { tags: ['Travel', 'TRAVEL'] });
  assert.deepEqual(store.recall(ids[0]).tags, ['TRAVEL', 'Travel']);
  assert.deepEqual(store.search('ferry', { tag: 'travel', limit: 2 }).map(n => n.id), [ids[3], ids[1]]);
  assert.deepEqual(store.search('ferry', { tag: 'travel' }).map(n => n.id), [ids[3], ids[1], ids[0]]);
  assert.deepEqual(store.search('ferry', { tag: 'trav' }), []);
  assert.deepEqual(store.search('ferry', { tag: 'work' }), []);
  assert.deepEqual(store.search('ferry').map(n => n.id), [ids[3], ids[1], ids[0]]);
  const note = store.write({ title: '  Literal %_\\\\ token  ', body: 'Exact symbols', tags: ['Travel', ' travel '] });
  assert.equal(note.title, 'Literal %_\\\\ token');
  assert.deepEqual(note.tags, ['travel']);
  assert.deepEqual(store.search('%_\\\\', { tag: 'TRAVEL' }).map(n => n.id), [note.id]);
  for (const args of [['', {}], ['ferry', { limit: 0 }], ['ferry', { limit: 101 }]]) {
    assert.throws(() => store.search(...args), NotesError);
  }
  assert.throws(() => store.write({ title: 'Invalid', body: '', tags: [''] }), NotesError);
  const response = handleMessage(store, { jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name: 'search_notes', arguments: { query: 'literal', tag: 'Travel' } } });
  assert.equal(response.result.isError, false);
  assert.deepEqual(JSON.parse(response.result.content[0].text).map(n => n.id), [note.id]);
  assert.equal(store.remove(note.id), true);
  assert.equal(store.
